mapper.select:
SELECT s.name, sc.subjectId, te.content, sc.countLessonTotal, c.courseName FROM Student s LEFT JOIN StudentCourse sc ON s.id = sc.studentId LEFT JOIN TeachEvaluation te ON s.id = te.studentId LEFT JOIN Course c ON sc.subjectId = c.subjectId
AND s.name = #{query.studentName}
AND sc.subjectId = #{query.courseName}
AND te.content = #{query.attendanceRecord}
AND sc.countLessonTotal = #{query.totalLessonHours}
